namespace sct::services {
CSize ExportSize(int sw,int sh,int mode,int percent,int width,int height){if(sw<1||sh<1||mode<0||mode>2||percent<1||percent>400)throw std::runtime_error("Invalid export scale");int64_t w=width,h=height;if(mode==0){w=std::max<int64_t>(1,(int64_t(sw)*percent+50)/100);h=std::max<int64_t>(1,(int64_t(sh)*percent+50)/100);}else if(mode==1)h=std::max<int64_t>(1,(int64_t(sh)*width+sw/2)/sw);if(w<1||h<1||w>32768||h>32768||uint64_t(sw)*sh*8+uint64_t(w)*h*12>512ULL*1024*1024)throw std::runtime_error("Export dimensions or working buffers exceed limit");return {int(w),int(h)};}
core::Image RenderScaledExport(const core::DocumentState& state,CSize size){if(!state.base)throw std::runtime_error("Missing export image");ExportSize(state.base->width,state.base->height,2,100,size.cx,size.cy);core::Image image;CString error;if(!RenderDocument(state,image,error))throw std::runtime_error("Cannot render scaled export");if(size.cx==image.width&&size.cy==image.height)return image;return core::Resize(image,size.cx,size.cy);}
core::Annotation RotatePictureAsset(const core::Annotation& original,double degrees){core::ValidateExtensions(original);if(original.tool!=core::Tool::Picture||original.locked||original.hidden||original.group||!original.asset||!std::isfinite(degrees)||degrees < -180||degrees>180)throw std::runtime_error("Select one unlocked ungrouped Picture and a valid angle");if(degrees==0)return original;const int w=original.rect.right-original.rect.left,h=original.rect.bottom-original.rect.top;if(w<1||h<1||uint64_t(w)*h*12>256ULL*1024*1024)throw std::runtime_error("Picture rotation buffer limit");core::Image image;if(!image.Create(w,h))throw std::runtime_error("Picture rotation allocation failed");std::fill(image.pixels.begin(),image.pixels.end(),BYTE{0});auto local=original;core::Document::Translate(local,-original.rect.left,-original.rect.top);if(!RenderObject(image,local))throw std::runtime_error("Cannot render selected Picture");auto rotated=core::RotateAngle(image,degrees,true,RGB(255,255,255),true);const int64_t left=int64_t(original.rect.left)+(int64_t(w)-rotated.width)/2,top=int64_t(original.rect.top)+(int64_t(h)-rotated.height)/2;if(left < -1000000||top < -1000000||left+rotated.width>1000000||top+rotated.height>1000000)throw std::runtime_error("Picture rotation coordinate limit");auto a=original;a.rect={LONG(left),LONG(top),LONG(left+rotated.width),LONG(top+rotated.height)};a.asset=std::make_shared<core::Image>(std::move(rotated));a.sourceCrop={};a.pictureMask=0;a.pictureAdjust=false;a.brightness=a.contrast=0;a.alpha=255;a.points.clear();core::ValidateExtensions(a);return a;}
std::vector<CString> BatchImagePaths(const BatchImagePlan& plan,size_t count){
    if(plan.directory.GetLength()!=int(wcslen(plan.directory.GetString()))||count<1||count>64||plan.files.empty()||plan.files.size()>64||plan.quality<1||plan.quality>100||(plan.format!=L"jpg"&&plan.format!=L"png"&&plan.format!=L"bmp")||!std::filesystem::path(plan.directory.GetString()).is_absolute()||!PathIsDirectory(plan.directory))throw std::runtime_error("Invalid batch folder, format or page count");
    auto less=[](const CString& a,const CString& b){return CompareStringOrdinal(a,-1,b,-1,TRUE)==CSTR_LESS_THAN;};std::set<CString,decltype(less)> used(less);std::set<size_t> pages;std::vector<CString> paths;
    for(const auto& file:plan.files){const auto& stem=file.stem;if(file.page>=count||!pages.insert(file.page).second||stem.IsEmpty()||stem.GetLength()>100||stem.Right(1)==L"."||stem.Right(1)==L" ")throw std::runtime_error("Invalid batch filename/page");for(int i=0;i<stem.GetLength();++i)if(stem[i]<32||wcschr(L"<>:\"/\\|?*",stem[i]))throw std::runtime_error("Invalid batch filename character");CString device=stem.SpanExcluding(L".");device.TrimRight(L" .");device.MakeUpper();if(device==L"CON"||device==L"PRN"||device==L"AUX"||device==L"NUL"||device==L"CONIN$"||device==L"CONOUT$"||device.GetLength()==4&&(device.Left(3)==L"COM"||device.Left(3)==L"LPT")&&(device[3]>=L'1'&&device[3]<=L'9'||device[3]==0xB9||device[3]==0xB2||device[3]==0xB3))throw std::runtime_error("Reserved batch filename");CString path=(std::filesystem::path(plan.directory.GetString())/std::filesystem::path((stem+L"."+plan.format).GetString())).lexically_normal().c_str();if(path.GetLength()>200||!used.insert(path).second||PathFileExists(path))throw std::runtime_error("Batch filename exists, duplicates another output or exceeds path limit");paths.push_back(std::move(path));}return paths;
}
std::vector<ImageExportOutcome> ExportImageBatch(const std::vector<core::DocumentState>& pages,const BatchImagePlan& plan){const auto paths=BatchImagePaths(plan,pages.size());std::vector<ImageExportOutcome> result;result.reserve(paths.size());for(size_t i=0;i<paths.size();++i){ImageExportOutcome outcome;outcome.path=paths[i];try{const auto& state=pages[plan.files[i].page];if(!state.base||uint64_t(state.base->pixels.size())*3>512ULL*1024*1024)throw std::runtime_error("Batch image working-buffer limit");core::Image image;std::vector<BYTE> bytes;if(RenderDocument(state,image,outcome.error)&&EncodeImage(image,plan.format,plan.quality,bytes,outcome.error))WriteBytes(outcome.path,bytes,outcome.error,false);}catch(const std::exception& e){outcome.error.Format(L"%hs",e.what());}result.push_back(std::move(outcome));}return result;}
}
